CREATE TABLE IF NOT EXISTS schema_migrations (version INT PRIMARY KEY, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS search_profiles (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL UNIQUE, enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS cpv_filters (id BIGINT PRIMARY KEY AUTO_INCREMENT, profile_id BIGINT NOT NULL, pattern VARCHAR(12) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(profile_id,pattern), FOREIGN KEY(profile_id) REFERENCES search_profiles(id));
CREATE TABLE IF NOT EXISTS tenders (id CHAR(32) PRIMARY KEY, public_id VARCHAR(64) NOT NULL UNIQUE, title TEXT NOT NULL, cpv VARCHAR(12), date_modified VARCHAR(40) NOT NULL, source_status VARCHAR(64), payload LONGTEXT NOT NULL, content_hash CHAR(64) NOT NULL, INDEX(date_modified), INDEX(cpv));
CREATE TABLE IF NOT EXISTS tender_sources (id BIGINT PRIMARY KEY AUTO_INCREMENT, tender_id CHAR(32) NOT NULL, source VARCHAR(30) NOT NULL, external_id VARCHAR(64) NOT NULL, date_modified VARCHAR(40) NOT NULL, UNIQUE(source,external_id), FOREIGN KEY(tender_id) REFERENCES tenders(id));
CREATE TABLE IF NOT EXISTS tender_revisions (id BIGINT PRIMARY KEY AUTO_INCREMENT, tender_id CHAR(32) NOT NULL, content_hash CHAR(64) NOT NULL, raw_json LONGTEXT NOT NULL, matched_filters TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(tender_id,content_hash), FOREIGN KEY(tender_id) REFERENCES tenders(id));
CREATE TABLE IF NOT EXISTS tender_items (tender_id CHAR(32) NOT NULL, item_key VARCHAR(120) NOT NULL, cpv VARCHAR(12), payload LONGTEXT NOT NULL, PRIMARY KEY(tender_id,item_key), FOREIGN KEY(tender_id) REFERENCES tenders(id));
CREATE TABLE IF NOT EXISTS collector_state (profile_id BIGINT NOT NULL, mode VARCHAR(16) NOT NULL, state_json LONGTEXT NOT NULL, PRIMARY KEY(profile_id,mode), FOREIGN KEY(profile_id) REFERENCES search_profiles(id));
CREATE TABLE IF NOT EXISTS collector_runs (id BIGINT PRIMARY KEY AUTO_INCREMENT, profile_id BIGINT NOT NULL, started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, finished_at TIMESTAMP NULL, state VARCHAR(24) NOT NULL, statistics LONGTEXT NOT NULL, FOREIGN KEY(profile_id) REFERENCES search_profiles(id));
CREATE TABLE IF NOT EXISTS sync_events (id BIGINT PRIMARY KEY AUTO_INCREMENT, tender_id CHAR(32) NOT NULL, revision_id BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(tender_id) REFERENCES tenders(id), FOREIGN KEY(revision_id) REFERENCES tender_revisions(id), INDEX(tender_id,id));
CREATE TABLE IF NOT EXISTS sync_clients (id VARCHAR(120) PRIMARY KEY, token_hash CHAR(64) NOT NULL UNIQUE, enabled BOOLEAN NOT NULL DEFAULT TRUE, last_seen TIMESTAMP NULL);
